        LOCALIZATION_LAYER_ID = None,
        PARALLAX = float('nan'),
        PMRA = float('nan'),
        PMDEC = float('nan'),
        REDSHIFT = float('nan'),
        REDSHIFT_UNC = float('nan'),
        DISTANCE_MPC = float('nan'),
        DISTANCE_UNC_MPC = float('nan'),
        SIZE_MAJOR_ARCSEC = float('nan'),
