        self.FALSE_ALARM_RATE_PER_YR = FALSE_ALARM_RATE_PER_YR  # type: float
        self.ALERT_STATE = ALERT_STATE  # type: int
        self.ALERT_REVISION = ALERT_REVISION  # type: int
        self.ISSUED_TIME = ISSUED_TIME  # type: Optional[str]
